pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 _number) internal {
        vm.assume(true);
        bool reverted;
        try c.setL1BlockValues(_number, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted);
    }

    function testFuzz_run(uint64 _number) public {
        _run(_number);
    }

    receive() external payable {}
}
